from datetime import date
from .modeller import Odunc, Uye


class KutuphaneServisi:
    def __init__(self):
        self.kitaplar = {}
        self.uyeler = {}
        self.kayitlar = []

    def kitap_ekle(self, kitap):
        self.kitaplar[kitap.id] = kitap

    def uye_ekle(self, uye):
        self.uyeler[uye.id] = uye

    def _aktif(self, kitap_id):
        return next((k for k in self.kayitlar if k.kitap_id == kitap_id and k.iade is None), None)

    def _odunc_suresi(self, kayit: Odunc) -> int:
        """İade tarihi üzerinden ödünç süresini hesapla (gün)."""
        return (kayit.iade - kayit.alinma).days

    def _ceza_hesapla(self, uye: Uye, sure: int) -> float:
        """Ceza hesapla."""
        günlük_ceza = 0.0
        ilk_7_gun = min(sure, 7)
        sonrakiler = sure - 7

        günlük_ceza += ilk_7_gun * 2.50
        if sure > 7:
            günlük_ceza += sonrakiler * 5.00

        # Maksimum 150 TL
        ceza = min(günlük_ceza, 150.0)

        # Öğrenci ise %50 indirim
        if uye.tur == "ogrenci":
            ceza = ceza * 0.5

        return round(ceza, 2)

    def odunc_ver(self, kitap_id, uye_id, tarih):
        """Kitabı üyeye verir. Kitap/üye yoksa ya da kitap zaten ödünçteyse ValueError."""
        if kitap_id not in self.kitaplar or uye_id not in self.uyeler:
            raise ValueError("kitap ya da üye bulunamadı")
        if self._aktif(kitap_id):
            raise ValueError("kitap zaten ödünçte")

        # Üye türüne göre kitap sınırı kontrolü
        uye = self.uyeler[uye_id]
        if uye.tur == "standart":
            max_odunc = 3
        else:  # ogrenci
            max_odunc = 5

        aktif_odunclar = [k for k in self.kayitlar if k.uye_id == uye_id and k.iade is None]
        if len(aktif_odunclar) >= max_odunc:
            raise ValueError(f"{uye.tur} üye için maksimum {max_odunc} adet ödünç")

        kayit = Odunc(kitap_id, uye_id, tarih)
        self.kayitlar.append(kayit)
        return kayit

    def iade_al(self, kitap_id, tarih):
        """Kitabın iadesini alır ve ödünç kaydını döndürür. Kitap ödünçte değilse ValueError."""
        kayit = self._aktif(kitap_id)
        if kayit is None:
            raise ValueError("kitap ödünçte değil")

        uye = self.uyeler[kayit.uye_id]
        sure = self._odunc_suresi(kayit)
        ceza = self._ceza_hesapla(uye, sure)

        kayit.iade = tarih
        kayit.ceza = ceza

        return kayit

    def oduncteki_kitaplar(self, uye_id):
        return sorted(k.kitap_id for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

    def toplam_ceza(self, uye_id: int) -> float:
        """Üyenin iade edilmiş tüm ödünçlerinin cezaları toplamı."""
        toplam = 0.0
        for kayit in self.kayitlar:
            if kayit.uye_id == uye_id and kayit.iade is not None:
                toplam += kayit.ceza
        return round(toplam, 2)

